package io.github.diodeme.ji.testkit;

import io.github.diodeme.ji.ai.Content;
import io.github.diodeme.ji.ai.Message;
import io.github.diodeme.ji.ai.ModelProvider;
import io.github.diodeme.ji.ai.ModelRequest;
import io.github.diodeme.ji.ai.ModelStreamEvent;
import io.github.diodeme.ji.ai.ProviderFailure;
import io.github.diodeme.ji.ai.Usage;
import java.time.Duration;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.concurrent.Flow;

/** Deterministic public-API faux provider for Core, Host, ACP, CLI, and Web tests. */
public final class ScriptedModelProvider implements ModelProvider {
    private final Deque<List<Step>> turns = new ArrayDeque<>();
    private final List<CapturedRequest> requests = new ArrayList<>();

    public ScriptedModelProvider enqueue(List<Step> steps) {
        synchronized (turns) { turns.addLast(List.copyOf(steps)); }
        return this;
    }

    public List<CapturedRequest> capturedRequests() {
        synchronized (requests) { return List.copyOf(requests); }
    }

    @Override
    public Flow.Publisher<ModelStreamEvent> stream(ModelRequest request) {
        List<Step> steps;
        synchronized (turns) {
            if (turns.isEmpty()) steps = List.of(new Step.Failure("internal.unexpected", Map.of(), 0));
            else steps = turns.removeFirst();
        }
        synchronized (requests) {
            requests.add(new CapturedRequest(request.sessionId(), request.model(), request.messages(), request.tools(), request.options()));
        }
        return subscriber -> subscriber.onSubscribe(new ScriptSubscription(subscriber, request, steps));
    }

    public sealed interface Step permits Step.Start, Step.Text, Step.Tool, Step.Wait, Step.Complete, Step.Failure {
        record Start(String responseId) implements Step {}
        record Text(String value) implements Step {}
        record Tool(String id, String name, Map<String, Object> arguments) implements Step { public Tool { arguments = Map.copyOf(arguments); } }
        record Wait(Gate gate) implements Step {}
        record Complete(Usage usage, ModelStreamEvent.StopReason reason) implements Step {}
        record Failure(String code, Map<String, String> parameters, long retryAfterMillis) implements Step {
            public Failure { parameters = Map.copyOf(parameters); }
        }
    }

    public static final class Gate {
        private final java.util.concurrent.CountDownLatch latch = new java.util.concurrent.CountDownLatch(1);
        public void open() { latch.countDown(); }
        private void await() throws InterruptedException { latch.await(); }
    }

    public record CapturedRequest(String sessionId, io.github.diodeme.ji.ai.ModelRef model, List<Message> messages,
                                  List<io.github.diodeme.ji.ai.ToolSchema> tools, Map<String, Object> options) {
        public CapturedRequest {
            messages = List.copyOf(messages);
            tools = List.copyOf(tools);
            options = Map.copyOf(options);
        }
    }

    private static final class ScriptSubscription implements Flow.Subscription {
        private final Flow.Subscriber<? super ModelStreamEvent> subscriber;
        private final ModelRequest request;
        private final List<Step> steps;
        private boolean started;
        private volatile boolean cancelled;
        ScriptSubscription(Flow.Subscriber<? super ModelStreamEvent> subscriber, ModelRequest request, List<Step> steps) {
            this.subscriber = subscriber; this.request = request; this.steps = steps;
        }
        @Override public synchronized void request(long amount) {
            if (started || cancelled || amount <= 0) return;
            started = true;
            Thread.startVirtualThread(this::run);
        }
        @Override public void cancel() { cancelled = true; }
        private void run() {
            try {
                for (Step step : steps) {
                    if (cancelled) return;
                    if (request.cancellation().isCancellationRequested()) {
                        subscriber.onNext(new ModelStreamEvent.Completed(Usage.ZERO, ModelStreamEvent.StopReason.ABORTED));
                        subscriber.onComplete();
                        return;
                    }
                    if (step instanceof Step.Start value) subscriber.onNext(new ModelStreamEvent.Started(value.responseId()));
                    else if (step instanceof Step.Text value) subscriber.onNext(new ModelStreamEvent.TextDelta(value.value()));
                    else if (step instanceof Step.Tool value) subscriber.onNext(new ModelStreamEvent.ToolCallReady(
                            new Content.ToolCall(value.id(), value.name(), value.arguments())));
                    else if (step instanceof Step.Wait value) value.gate().await();
                    else if (step instanceof Step.Complete value) {
                        subscriber.onNext(new ModelStreamEvent.Completed(value.usage(), value.reason()));
                        subscriber.onComplete();
                        return;
                    } else if (step instanceof Step.Failure value) {
                        Optional<Duration> retry = value.retryAfterMillis() > 0
                                ? Optional.of(Duration.ofMillis(value.retryAfterMillis())) : Optional.empty();
                        subscriber.onNext(new ModelStreamEvent.Failed(new ProviderFailure(value.code(), value.parameters(), retry)));
                        subscriber.onComplete();
                        return;
                    }
                }
                subscriber.onError(new IllegalStateException("faux script has no terminal step"));
            } catch (InterruptedException exception) {
                Thread.currentThread().interrupt();
                subscriber.onError(exception);
            }
        }
    }
}
